const outputDirectory = new URL("../apps/studio/assets/i18n/", import.meta.url);
mkdirSync(outputDirectory, { recursive: true });
for (const [languageIndex, language] of languages.entries()) {
  const bundle = Object.fromEntries(rows.map(([key, ...translations]) => [key, translations[languageIndex]]));
  writeFileSync(new URL(`${language}.json`, outputDirectory), `${JSON.stringify(bundle, null, 2)}\n`);
}

console.log(`i18n-generation status=ok languages=${languages.length} keys=${rows.length}`);
